private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb){
    int cp;
    if ((i & 0x80) == 0) { // 1-byte UTF-8 (ASCII)
        cp = i & 0x7F;
        sb.append((char)cp);
        return 1;
    }
    if ((i & 0xE0) == 0xC0) { // 2-byte sequence
        int b1 = bb.get() & 0xFF;
        if ((b1 & 0xC0) != 0x80) {
            sb.append('\uFFFD'); // Replacement character for invalid sequence
            return 1;
        }
        cp = ((i & 0x1F) << 6) | (b1 & 0x3F);
        sb.append((char)cp);
        return 2;
    }
    if ((i & 0xF0) == 0xE0) { // 3-byte sequence
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
            sb.append('\uFFFD');
            return 1;
        }
        cp = ((i & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        sb.append((char)cp);
        return 3;
    }
    if ((i & 0xF8) == 0xF0) { // 4-byte sequence, needs surrogate pairs
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
            sb.append('\uFFFD');
            return 1;
        }
        cp = ((i & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        // map to surrogate pair
        cp -= 0x10000;
        char high = (char)((cp >> 10) + 0xD800);
        char low  = (char)((cp & 0x3FF) + 0xDC00);
        sb.append(high);
        sb.append(low);
        return 4;
    }
    // Invalid leading byte
    sb.append('\uFFFD');
    return 1;
