    // Allocate an array large enough to hold the frame header (offset, #locals, #stack)
    // and the subsequent local / stack variable descriptors.
    // The header itself takes three entries.
    this.currentFrame = new int[numLocal + numStack + 3];
    // Store the header information: offset of the frame, number of local variables,
