private void enlarge(final int size) {
    // Ensure there is enough capacity to add `size` more bytes.  
    // Current number of stored bytes is `count`. The backing array is `buf`.
    int minCapacity = count + size;
    if (minCapacity > buf.length) {
        int newCapacity = buf.length * 2 + 8; // grow by factor of ~2 with reserve margin
        if (newCapacity < minCapacity) {
            newCapacity = minCapacity; // meet minimum requirement
        }
        // Avoid overflow, clamp to Integer.MAX_VALUE if needed
        if (newCapacity < 0) {
            newCapacity = Integer.MAX_VALUE;
        }
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
