private int parseEndOfLine(String headerPart,int end){
    // Scan for the CRLF sequence starting from the given index.
    for (int i = end; i < headerPart.length() - 1; i++){
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    // If only a lone '\n' is present, return its index.
    for (int i = end; i < headerPart.length(); i++){
        if (headerPart.charAt(i) == '\n'){
            return i;
        }
    }
    // No line break found.
    return -1;
