public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        deleteOnExitRecursive(file);
    } else {
        try {
            file.deleteOnExit();
        } catch (SecurityException e) {
            throw new IOException("Failed to register file for deletion: " + file.getAbsolutePath(), e);
        }
    }
}

private static void deleteOnExitRecursive(File dir) throws IOException {
    File[] files = dir.listFiles();
    if (files == null) {
        throw new IOException("Unable to list contents of directory: " + dir.getAbsolutePath());
    }
    for (File f : files) {
        if (f.isDirectory()) {
            deleteOnExitRecursive(f);
        } else {
            try {
                f.deleteOnExit();
            } catch (SecurityException e) {
                throw new IOException("Failed to register file for deletion: " + f.getAbsolutePath(), e);
            }
        }
    }
    try {
        dir.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Failed to register directory for deletion: " + dir.getAbsolutePath(), e);
    }
