protected int findByte(byte value, int pos) {
    // If the buffer is not initialized, we cannot find anything.
    if (buffer == null) {
        return -1;
    }
    // Clamp the start position to the valid range.
    if (pos < 0) {
        pos = 0;
    }
    // Ensure we don't start beyond the end of the buffer.
    if (pos >= buffer.length) {
        return -1;
    }
    // Search for the byte, returning the index when found.
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found.
    return -1;
