public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping of the specified table from the index
    Mappings current = getCurrentMappings(tableName);
    if (current == null) {
        return new Mappings();
    }

    Map<String, Object> currentProps = current.getProperties();
    Map<String, Object> oldProps = mappings.getProperties();

    Map<String, Object> diffProps = new HashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if ("_source".equals(field)) {
            // Skip _source config to avoid conflict with current index
            continue;
        }
        if (!oldProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }
    return new Mappings(diffProps);
