protected List<TimeRange> buildTimeRanges(long start, long end) {
    // If start is not less than end, there is nothing to split.
    if (start >= end) {
        return Collections.emptyList();
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long cursor = start;

    while (cursor < end) {
        long next = cursor + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        timeRanges.add(new TimeRange(cursor, next));
        cursor = next;
    }

    return timeRanges;
