public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException();
    }
    int size = 0;
    final int end = index + len;
    int i = index;
    while (i < end) {
        char c = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(c)) {
            if (i + 1 >= end || !Character.isLowSurrogate(str.charAt(i + 1))) {
                throw new IllegalArgumentException("Unmatched surrogate at position " + i);
            }
            codePoint = Character.toCodePoint(c, str.charAt(i + 1));
            i += 2;
        } else if (Character.isLowSurrogate(c)) {
            throw new IllegalArgumentException("Unmatched low surrogate at position " + i);
        } else {
            codePoint = c;
            i += 1;
        }
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}<|return|>

