public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1; // ignore leading slash for absolute paths
    }
    for (int i = start; i <= path.length(); i++) {
        int next = path.indexOf('/', i);
        String segment;
        if (next == -1) {
            segment = path.substring(i);
            i = path.length(); // exit after last segment
        } else {
            segment = path.substring(i, next);
            i = next; // next iteration will skip '/'
        }
        if (segment.isEmpty()) {
            continue; // skip empty segments (consecutive slashes)
        }
        String decoded = segment;
        if (decode) {
            decoded = percentDecode(segment);
        }
        result.add(new PathSegmentImpl(decoded));
    }
    return result;
