public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int n = desiredCapacity;
    if ((n & 1) == 0) {
        // Make n odd unless it is 2
        if (n == 2) {
            return 2;
        }
        n++;
    }
    while (!isPrime(n)) {
        n += 2; // Only check odd candidates
        // Handle potential overflow
        if (n <= 0) {
            n = Integer.MAX_VALUE;
            break;
        }
    }
    return n;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    int sqrt = (int)Math.sqrt(n);
    for (int i = 5; i <= sqrt; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
