public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Abbreviate the name stored in the instance (assumed to be a field named "name")
    // from the position nameStart to the end, by appending the first letter of each
    // word followed by a dot to the provided buffer.
    if (name == null) {
