    if (nameStart >= name.length()) {
        return;
    }
    final String sub = name.substring(nameStart);
    // Split by any whitespace to isolate words
    final String[] words = sub.split("\\s+");
    for (String word : words) {
        if (word.isEmpty()) {
            continue;
