        for (K candidate : keys) {
            if (candidate == key) continue;
            @SuppressWarnings("unchecked")
            Comparable<? super K> comp = (Comparable<? super K>) candidate;
            if (comp.compareTo(key) < 0) {
                Integer value = ((Number) candidate).intValue();
                if (lower == null || value > lower) {
                    lower = value;
