public static String applyRelativePath(String path,String relativePath){
    // Determine if the original path is absolute
    boolean isAbsolute = path != null && path.startsWith("/");

    // Split the base path into segments, ignoring empty parts
    String[] baseSegments = path != null ? path.split("/") : new String[0];
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    for (String seg : baseSegments) {
        if (seg == null || seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        stack.addLast(seg);
    }

    // Process each component of the relative path
    if (relativePath != null) {
        String[] relativeSegments = relativePath.split("/");
        for (String seg : relativeSegments) {
            if (seg == null || seg.isEmpty() || seg.equals(".")) {
                continue;
            }
            if (seg.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(seg);
            }
        }
    }

    // Build the resulting path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }

    java.util.Iterator<String> it = stack.iterator();
    boolean first = true;
    while (it.hasNext()) {
        if (!first && !isAbsolute) {
            sb.append("/");
        } else if (!first && isAbsolute && sb.length() > 1) {
            sb.append("/");
        } else if (first && !isAbsolute) {
            // nothing
        }
        sb.append(it.next());
        first = false;
    }

    // Handle the case where the result is empty (root)
    if (!isAbsolute && sb.length() == 0) {
        return "";
    }
    if (isAbsolute && sb.length() == 0) {
        return "/";
    }

    return sb.toString();
